using UnityEngine;
namespace CelestialMaker {
 public sealed class Cosmos:MonoBehaviour {
  public Material material; Transform[] orbits; AudioSource ambient; int previousStage=-1,previousTheme=-1;Transform visualRoot;
  void Ornament(Transform body,int stage){if(stage==1||stage==5){var ring=new GameObject("Orbital shell",typeof(LineRenderer));ring.transform.SetParent(body,false);var line=ring.GetComponent<LineRenderer>();line.useWorldSpace=false;line.loop=true;line.positionCount=64;line.startWidth=line.endWidth=.018f;line.sharedMaterial=material;for(int p=0;p<64;p++){float a=p*Mathf.PI*2/64;line.SetPosition(p,new Vector3(Mathf.Cos(a)*1.25f,Mathf.Sin(a)*.65f,0));}}if(stage==4){body.localScale=new Vector3(body.localScale.x*1.4f,body.localScale.y*.65f,.15f);for(int arm=0;arm<3;arm++){var go=new GameObject("Spiral arm",typeof(LineRenderer));go.transform.SetParent(body,false);var line=go.GetComponent<LineRenderer>();line.useWorldSpace=false;line.positionCount=32;line.startWidth=.045f;line.endWidth=.008f;line.sharedMaterial=material;for(int p=0;p<32;p++){float r=.08f+p*.025f,a=p*.16f+arm*Mathf.PI*2/3;line.SetPosition(p,new Vector3(Mathf.Cos(a)*r,Mathf.Sin(a)*r,-.1f));}}}}
  void Start(){visualRoot=new GameObject("Cosmic scene geometry").transform;visualRoot.SetParent(transform,false);var sun=new GameObject("Cosmic key light").AddComponent<Light>();sun.transform.SetParent(visualRoot);sun.type=LightType.Directional;sun.intensity=1.2f;sun.shadows=LightShadows.None;sun.transform.rotation=Quaternion.Euler(35,-40,0);orbits=new Transform[36];var rng=new System.Random(1701);for(int i=0;i<orbits.Length;i++){var go=new GameObject("Celestial body",typeof(MeshFilter),typeof(MeshRenderer));go.GetComponent<MeshFilter>().sharedMesh=Resources.Load<Mesh>("body-mesh");go.name="Celestial body "+i;go.transform.SetParent(visualRoot);float scale=i<24?.06f:.5f+(i-24)*.075f;go.transform.localScale=Vector3.one*scale;go.transform.localPosition=new Vector3((float)(rng.NextDouble()*24-12),(float)(rng.NextDouble()*14-7),(float)(rng.NextDouble()*8));var r=go.GetComponent<Renderer>();r.sharedMaterial=material;var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",Color.Lerp(new Color(.2f,.8f,.85f),new Color(.95f,.5f,.25f),(float)rng.NextDouble()));if(i>=28&&i<30)block.SetTexture("_BaseMap",Resources.Load<Texture2D>("planet-surface"));r.SetPropertyBlock(block);orbits[i]=go.transform;if(i>=24)Ornament(go.transform,(i-24)/2);}
   ambient=gameObject.AddComponent<AudioSource>();ambient.loop=true;int sr=22050;float[] samples=new float[sr*8];for(int i=0;i<samples.Length;i++){double t=(double)i/sr;samples[i]=(float)(.055*(System.Math.Sin(2*System.Math.PI*110*t)+.5*System.Math.Sin(2*System.Math.PI*165*t)+.25*System.Math.Sin(2*System.Math.PI*220*t)));}var clip=AudioClip.Create("Original cosmic ambient",samples.Length,1,sr,false);clip.SetData(samples,0);ambient.clip=clip;
  }
  void OnDestroy(){if(ambient&&ambient.clip)Destroy(ambient.clip);}
  void Update(){var s=GameSession.Instance?.Sim?.S;if(s==null)return;if(!ambient.isPlaying&&UnityEngine.InputSystem.Pointer.current!=null&&UnityEngine.InputSystem.Pointer.current.press.wasPressedThisFrame)ambient.Play();ambient.volume=s.settings.music;bool hidden=!Application.isMobilePlatform&&Application.platform!=RuntimePlatform.WebGLPlayer&&Screen.width>=Screen.height;if(visualRoot.gameObject.activeSelf==hidden)visualRoot.gameObject.SetActive(!hidden);if(hidden)return;int theme=GameSession.Instance.Sim.CosmeticsUnlocked?s.settings.theme:0;if(theme!=previousTheme){previousTheme=theme;for(int i=0;i<orbits.Length;i++){var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",theme==1?Color.Lerp(new Color(.8f,.4f,1),new Color(.3f,.7f,1),i/36f):theme==2?Color.Lerp(new Color(1,.4f,.2f),new Color(.9f,.8f,.4f),i/36f):Color.Lerp(new Color(.2f,.8f,.85f),new Color(.95f,.5f,.25f),i/36f));if(i>=28&&i<30)block.SetTexture("_BaseMap",Resources.Load<Texture2D>("planet-surface"));orbits[i].GetComponent<Renderer>().SetPropertyBlock(block);}}int stage=0;for(int i=0;i<6;i++)if(GameSession.Instance.Sim.StageOpen(i))stage=i;if(stage!=previousStage){previousStage=stage;for(int i=24;i<36;i++)orbits[i].gameObject.SetActive(i-24<=stage*2+1);}if(s.settings.reducedMotion)return;for(int i=0;i<orbits.Length;i++)orbits[i].RotateAround(Vector3.zero,Vector3.forward,Time.deltaTime*(i<24?.08f:.8f));}
 }
}





